# [doc = " A one-pass DFA for executing a subset of anchored regex searches while"] # [doc = " resolving capturing groups."] # [doc = ""] # [doc = " A one-pass DFA can be built from an NFA that is one-pass. An NFA is"] # [doc = " one-pass when there is never any ambiguity about how to continue a search."] # [doc = " For example, `a*a` is not one-pass because during a search, it's not"] # [doc = " possible to know whether to continue matching the `a*` or to move on to"] # [doc = " the single `a`. However, `a*b` is one-pass, because for every byte in the"] # [doc = " input, it's always clear when to move on from `a*` to `b`."] # [doc = ""] # [doc = " # Only anchored searches are supported"] # [doc = ""] # [doc = " In this crate, especially for DFAs, unanchored searches are implemented by"] # [doc = " treating the pattern as if it had a `(?s-u:.)*?` prefix. While the prefix"] # [doc = " is one-pass on its own, adding anything after it, e.g., `(?s-u:.)*?a` will"] # [doc = " make the overall pattern not one-pass. Why? Because the `(?s-u:.)` matches"] # [doc = " any byte, and there is therefore ambiguity as to when the prefix should"] # [doc = " stop matching and something else should start matching."] # [doc = ""] # [doc = " Therefore, one-pass DFAs do not support unanchored searches. In addition"] # [doc = " to many regexes simply not being one-pass, it implies that one-pass DFAs"] # [doc = " have limited utility. With that said, when a one-pass DFA can be used, it"] # [doc = " can potentially provide a dramatic speed up over alternatives like the"] # [doc = " [`BoundedBacktracker`](crate::nfa::thompson::backtrack::BoundedBacktracker)"] # [doc = " and the [`PikeVM`](crate::nfa::thompson::pikevm::PikeVM). In particular,"] # [doc = " a one-pass DFA is the only DFA capable of reporting the spans of matching"] # [doc = " capturing groups."] # [doc = ""] # [doc = " To clarify, when we say that unanchored searches are not supported, what"] # [doc = " that actually means is:"] # [doc = ""] # [doc = " * The high level routines, [`DFA::is_match`] and [`DFA::captures`], always"] # [doc = " do anchored searches."] # [doc = " * Since iterators are most useful in the context of unanchored searches,"] # [doc = " there is no `DFA::captures_iter` method."] # [doc = " * For lower level routines like [`DFA::try_search`], an error will be"] # [doc = " returned if the given [`Input`] is configured to do an unanchored search or"] # [doc = " search for an invalid pattern ID. (Note that an [`Input`] is configured to"] # [doc = " do an unanchored search by default, so just giving a `Input::new` is"] # [doc = " guaranteed to return an error.)"] # [doc = ""] # [doc = " # Other limitations"] # [doc = ""] # [doc = " In addition to the [configurable heap limit](Config::size_limit) and"] # [doc = " the requirement that a regex pattern be one-pass, there are some other"] # [doc = " limitations:"] # [doc = ""] # [doc = " * There is an internal limit on the total number of explicit capturing"] # [doc = " groups that appear across all patterns. It is somewhat small and there is"] # [doc = " no way to configure it. If your pattern(s) exceed this limit, then building"] # [doc = " a one-pass DFA will fail."] # [doc = " * If the number of patterns exceeds an internal unconfigurable limit, then"] # [doc = " building a one-pass DFA will fail. This limit is quite large and you're"] # [doc = " unlikely to hit it."] # [doc = " * If the total number of states exceeds an internal unconfigurable limit,"] # [doc = " then building a one-pass DFA will fail. This limit is quite large and"] # [doc = " you're unlikely to hit it."] # [doc = ""] # [doc = " # Other examples of regexes that aren't one-pass"] # [doc = ""] # [doc = " One particularly unfortunate example is that enabling Unicode can cause"] # [doc = " regexes that were one-pass to no longer be one-pass. Consider the regex"] # [doc = " `(?-u)\\w*\\s` for example. It is one-pass because there is exactly no"] # [doc = " overlap between the ASCII definitions of `\\w` and `\\s`. But `\\w*\\s`"] # [doc = " (i.e., with Unicode enabled) is *not* one-pass because `\\w` and `\\s` get"] # [doc = " translated to UTF-8 automatons. And while the *codepoints* in `\\w` and `\\s`"] # [doc = " do not overlap, the underlying UTF-8 encodings do. Indeed, because of the"] # [doc = " overlap between UTF-8 automata, the use of Unicode character classes will"] # [doc = " tend to vastly increase the likelihood of a regex not being one-pass."] # [doc = ""] # [doc = " # How does one know if a regex is one-pass or not?"] # [doc = ""] # [doc = " At the time of writing, the only way to know is to try and build a one-pass"] # [doc = " DFA. The one-pass property is checked while constructing the DFA."] # [doc = ""] # [doc = " This does mean that you might potentially waste some CPU cycles and memory"] # [doc = " by optimistically trying to build a one-pass DFA. But this is currently the"] # [doc = " only way. In the future, building a one-pass DFA might be able to use some"] # [doc = " heuristics to detect common violations of the one-pass property and bail"] # [doc = " more quickly."] # [doc = ""] # [doc = " # Resource usage"] # [doc = ""] # [doc = " Unlike a general DFA, a one-pass DFA has stricter bounds on its resource"] # [doc = " usage. Namely, construction of a one-pass DFA has a time and space"] # [doc = " complexity of `O(n)`, where `n ~ nfa.states().len()`. (A general DFA's time"] # [doc = " and space complexity is `O(2^n)`.) This smaller time bound is achieved"] # [doc = " because there is at most one DFA state created for each NFA state. If"] # [doc = " additional DFA states would be required, then the pattern is not one-pass"] # [doc = " and construction will fail."] # [doc = ""] # [doc = " Note though that currently, this DFA uses a fully dense representation."] # [doc = " This means that while its space complexity is no worse than an NFA, it may"] # [doc = " in practice use more memory because of higher constant factors. The reason"] # [doc = " for this trade off is two-fold. Firstly, a dense representation makes the"] # [doc = " search faster. Secondly, the bigger an NFA, the more unlikely it is to be"] # [doc = " one-pass. Therefore, most one-pass DFAs are usually pretty small."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows that the one-pass DFA implements Unicode word boundaries"] # [doc = " correctly while simultaneously reporting spans for capturing groups that"] # [doc = " participate in a match. (This is the only DFA that implements full support"] # [doc = " for Unicode word boundaries.)"] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{dfa::onepass::DFA, Match, Span};"] # [doc = ""] # [doc = " let re = DFA::new(r\"\\b(?P<first>\\w+)[[:space:]]+(?P<last>\\w+)\\b\")?;"] # [doc = " let (mut cache, mut caps) = (re.create_cache(), re.create_captures());"] # [doc = ""] # [doc = " re.captures(&mut cache, \"Шерлок Холмс\", &mut caps);"] # [doc = " assert_eq!(Some(Match::must(0, 0..23)), caps.get_match());"] # [doc = " assert_eq!(Some(Span::from(0..12)), caps.get_group_by_name(\"first\"));"] # [doc = " assert_eq!(Some(Span::from(13..23)), caps.get_group_by_name(\"last\"));"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: iteration"] # [doc = ""] # [doc = " Unlike other regex engines in this crate, this one does not provide"] # [doc = " iterator search functions. This is because a one-pass DFA only supports"] # [doc = " anchored searches, and so iterator functions are generally not applicable."] # [doc = ""] # [doc = " However, if you know that all of your matches are"] # [doc = " directly adjacent, then an iterator can be used. The"] # [doc = " [`util::iter::Searcher`](crate::util::iter::Searcher) type can be used for"] # [doc = " this purpose:"] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{"] # [doc = "     dfa::onepass::DFA,"] # [doc = "     util::iter::Searcher,"] # [doc = "     Anchored, Input, Span,"] # [doc = " };"] # [doc = ""] # [doc = " let re = DFA::new(r\"\\w(\\d)\\w\")?;"] # [doc = " let (mut cache, caps) = (re.create_cache(), re.create_captures());"] # [doc = " let input = Input::new(\"a1zb2yc3x\").anchored(Anchored::Yes);"] # [doc = ""] # [doc = " let mut it = Searcher::new(input).into_captures_iter(caps, |input, caps| {"] # [doc = "     Ok(re.try_search(&mut cache, input, caps)?)"] # [doc = " }).infallible();"] # [doc = " let caps0 = it.next().unwrap();"] # [doc = " assert_eq!(Some(Span::from(1..2)), caps0.get_group(1));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone)] pub struct DFA { # [doc = " The configuration provided by the caller."] config : Config , # [doc = " The NFA used to build this DFA."] # [doc = ""] # [doc = " NOTE: We probably don't need to store the NFA here, but we use enough"] # [doc = " bits from it that it's convenient to do so. And there really isn't much"] # [doc = " cost to doing so either, since an NFA is reference counted internally."] nfa : NFA , # [doc = " The transition table. Given a state ID 's' and a byte of haystack 'b',"] # [doc = " the next state is `table[sid + classes[byte]]`."] # [doc = ""] # [doc = " The stride of this table (i.e., the number of columns) is always"] # [doc = " a power of 2, even if the alphabet length is smaller. This makes"] # [doc = " converting between state IDs and state indices very cheap."] # [doc = ""] # [doc = " Note that the stride always includes room for one extra \"transition\""] # [doc = " that isn't actually a transition. It is a 'PatternEpsilons' that is"] # [doc = " used for match states only. Because of this, the maximum number of"] # [doc = " active columns in the transition table is 257, which means the maximum"] # [doc = " stride is 512 (the next power of 2 greater than or equal to 257)."] table : Vec < Transition > , # [doc = " The DFA state IDs of the starting states."] # [doc = ""] # [doc = " `starts[0]` is always present and corresponds to the starting state"] # [doc = " when searching for matches of any pattern in the DFA."] # [doc = ""] # [doc = " `starts[i]` where i>0 corresponds to the starting state for the pattern"] # [doc = " ID 'i-1'. These starting states are optional."] starts : Vec < StateID > , # [doc = " Every state ID >= this value corresponds to a match state."] # [doc = ""] # [doc = " This is what a search uses to detect whether a state is a match state"] # [doc = " or not. It requires only a simple comparison instead of bit-unpacking"] # [doc = " the PatternEpsilons from every state."] min_match_id : StateID , # [doc = " The alphabet of this DFA, split into equivalence classes. Bytes in the"] # [doc = " same equivalence class can never discriminate between a match and a"] # [doc = " non-match."] classes : ByteClasses , # [doc = " The number of elements in each state in the transition table. This may"] # [doc = " be less than the stride, since the stride is always a power of 2 and"] # [doc = " the alphabet length can be anything up to and including 256."] alphabet_len : usize , # [doc = " The number of columns in the transition table, expressed as a power of"] # [doc = " 2."] stride2 : usize , # [doc = " The offset at which the PatternEpsilons for a match state is stored in"] # [doc = " the transition table."] # [doc = ""] # [doc = " PERF: One wonders whether it would be better to put this in a separate"] # [doc = " allocation, since only match states have a non-empty PatternEpsilons"] # [doc = " and the number of match states tends be dwarfed by the number of"] # [doc = " non-match states. So this would save '8*len(non_match_states)' for each"] # [doc = " DFA. The question is whether moving this to a different allocation will"] # [doc = " lead to a perf hit during searches. You might think dealing with match"] # [doc = " states is rare, but some regexes spend a lot of time in match states"] # [doc = " gobbling up input. But... match state handling is already somewhat"] # [doc = " expensive, so maybe this wouldn't do much? Either way, it's worth"] # [doc = " experimenting."] pateps_offset : usize , # [doc = " The first explicit slot index. This refers to the first slot appearing"] # [doc = " immediately after the last implicit slot. It is always 'patterns.len()"] # [doc = " * 2'."] # [doc = ""] # [doc = " We record this because we only store the explicit slots in our DFA"] # [doc = " transition table that need to be saved. Implicit slots are handled"] # [doc = " automatically as part of the search."] explicit_slot_start : usize , }
